-- Migration 20261024063419_review_queue: generated by drizzle-kit, hand-reviewed before commit.
-- Reviewed-by: Claude (agent, #518)
-- The Data Ops review and correction queue (#518, D-049). review_item is global (GLOBAL_TABLES) and
-- holds no workspace; the app role may SELECT, INSERT and UPDATE it. review_correction is the tenant
-- table a fix fans out into: FORCE RLS with ws_isolation. app_review_propagate(item) is the only
-- cross-workspace write: SECURITY DEFINER, refusing (42501) anyone but an enabled staff_user, it
-- reads the watches of the item's source and CNR (owner_definer_read on case_watch) and inserts one
-- corrected row per watching proceeding (owner_definer_write on review_correction). Additive only.
CREATE TABLE "review_correction" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"proceeding_id" uuid NOT NULL,
	"review_item_id" uuid NOT NULL,
	"field" text NOT NULL,
	"value" text NOT NULL,
	"source_type" "source_type" NOT NULL,
	"source_ref" text,
	"anchor_id" uuid,
	"confidence" numeric(4, 3),
	"confirmation_state" "confirmation_state" DEFAULT 'proposed' NOT NULL,
	"captured_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "review_correction_workspace_proceeding_item_uq" UNIQUE("workspace_id","proceeding_id","review_item_id"),
	CONSTRAINT "review_correction_field_chk" CHECK ("review_correction"."field" in ('next_date', 'stage', 'bench')),
	CONSTRAINT "review_correction_provenance_chk" CHECK ((source_type = 'manual' or anchor_id is not null or source_ref is not null) and (confidence is null or (confidence >= 0 and confidence <= 1)))
);
--> statement-breakpoint
CREATE TABLE "review_item" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"kind" text NOT NULL,
	"source_id" text NOT NULL,
	"cnr" text,
	"field" text,
	"shown_value" text,
	"reported_value" text,
	"detail" text,
	"consent" boolean DEFAULT false NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"assignee_id" uuid,
	"due_at" timestamp with time zone NOT NULL,
	"corrected_value" text,
	"resolved_by" uuid,
	"resolved_at" timestamp with time zone,
	"fixture_exported_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "review_item_kind_chk" CHECK ("review_item"."kind" in ('low_confidence', 'conflict', 'user_report')),
	CONSTRAINT "review_item_status_chk" CHECK ("review_item"."status" in ('open', 'in_review', 'fixed', 'dismissed')),
	CONSTRAINT "review_item_field_chk" CHECK ("review_item"."field" is null or "review_item"."field" in ('next_date', 'stage', 'bench')),
	CONSTRAINT "review_item_report_chk" CHECK ("review_item"."kind" <> 'user_report' or ("review_item"."consent" and "review_item"."cnr" is not null and "review_item"."field" is not null)),
	CONSTRAINT "review_item_fixed_chk" CHECK ("review_item"."status" <> 'fixed' or ("review_item"."corrected_value" is not null and "review_item"."resolved_at" is not null))
);
--> statement-breakpoint
