CREATE FUNCTION app_review_propagate(item uuid)
  RETURNS bigint
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    #variable_conflict use_column
    DECLARE
      r review_item%ROWTYPE;
      n bigint;
    BEGIN
      PERFORM app_staff_require_caller();
      SELECT * INTO r FROM review_item WHERE id = item;
      IF NOT FOUND OR r.status <> 'fixed' OR r.cnr IS NULL OR r.field IS NULL THEN
        RAISE EXCEPTION 'review item % is not a fixed record correction', item
          USING ERRCODE = 'check_violation';
      END IF;
      INSERT INTO review_correction
          (workspace_id, proceeding_id, review_item_id, field, value, source_type, source_ref,
           confirmation_state)
        SELECT DISTINCT w.workspace_id, w.proceeding_id, r.id, r.field, r.corrected_value,
               'system'::source_type, 'causedeck-review:' || r.id::text, 'corrected'::confirmation_state
          FROM case_watch w
         WHERE w.source_id = r.source_id AND w.cnr = r.cnr
        ON CONFLICT (workspace_id, proceeding_id, review_item_id) DO NOTHING;
      GET DIAGNOSTICS n = ROW_COUNT;
      RETURN n;
    END
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_review_propagate(uuid) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_review_propagate(uuid) TO causedeck_app, causedeck_clerk;
